<!-- about.html -->
<div class="post">
  <header class="post-header">
    <h1 class="post-title">
      <img src="{{ site.logo | prepend: 'assets/img/' }}" class="inline-logo" />
      {% if site.title == "blank" -%}<span class="font-weight-bold">{{ site.first_name }}</span> {{ site.middle_name }}
      {{ site.last_name }}{%- else -%}{{ site.title }}{%- endif %}
    </h1>
    <p class="desc">{{ page.subtitle }}</p>
  </header>

  <article>
    {% if page.profile -%}
    <div class="profile float-{%- if page.profile.align == 'left' -%}left{%- else -%}right{%- endif -%}">
      {%- if page.profile.image %}
      {%- assign profile_image_path = page.profile.image | prepend: 'assets/img/' -%}

      {% if page.profile.image_circular %}
      {%- assign profile_image_class = "img-fluid z-depth-1 rounded-circle" -%}
      {% else %}
      {%- assign profile_image_class = "img-fluid z-depth-1 rounded" -%}
      {% endif %}


      {% include figure.html
      path=profile_image_path
      class=profile_image_class
      alt=page.profile.image
      zoomable=true
      caption=page.profile.image_caption -%}
      {% endif -%}
      {%- if page.profile.address %}
      <div class="address">
        {{ page.profile.address }}
      </div>
      {%- endif %}
    </div>
    {%- endif %}

    <div class="clearfix">
      {{ content }}
    </div>

    <!-- News -->
    {% if page.news -%}
    <h2><a href="{{ '/news/' | relative_url }}" style="color: inherit;">news</a></h2>
    {%- include news.html %}
    {%- endif %}
    <div float-right>

    </div>

    <!-- Selected papers -->
    {% if page.selected_papers -%}
    <h2><a href="{{ '/publications/' | relative_url }}" style="color: inherit;">selected publications</a></h2>
    {%- include selected_papers.html %}
    {%- endif %}

    <!-- Social -->
    {%- if page.social %}
    <div class="social">
      <div class="contact-icons">
        {% include social.html %}
      </div>

      <div class="contact-note">
        {{ site.contact_note }}
      </div>

    </div>
    {%- endif %}
  </article>

</div>","totalLinesInFile":78}

{"contents":"{%- assign img_path = include.path | remove: ".jpg" | remove: ".jpeg" | remove: ".png" | remove: ".tiff" -%}

<figure>

  <picture>
    {% if site.imagemagick.enabled %}
    {% for i in site.imagemagick.widths -%}
      <source 
        class="responsive-img-srcset"
        media="(max-width: {{ i }}px)" 
        srcset="{{ img_path | relative_url }}-{{ i }}.webp"
      />
    {% endfor -%}
    {% endif %}

    <!-- Fallback to the original file -->
    <img 
      src="{{ include.path | relative_url }}"
      {% if include.class %}class="{{ include.class }}"{% endif %}  
      {% if include.width %}width="{{ include.width }}"{% else %}width="auto"{% endif %} 
      {% if include.height %}height="{{ include.height }}"{% else %}height="auto"{% endif %} 
      {% if include.min-width %}min-width="{{ include.min-width }}"{% endif %} 
      {% if include.min-height %}min-height="{{ include.min-height }}"{% endif %} 
      {% if include.max-width %}max-width="{{ include.max-width }}"{% endif %} 
      {% if include.max-height %}height="{{ include.max-height }}"{% endif %} 
      {% if include.alt %}alt="{{ include.alt }}"{% endif %} 
      {% if include.title %}title="{{ include.title }}"{% endif %} 
      {% if include.zoomable %}data-zoomable{% endif %}
      onerror="this.onerror=null; $('.responsive-img-srcset').remove();"
    />

  </picture>

  {%- if include.caption -%}<figcaption class="caption">{{ include.caption }}</figcaption>{%- endif %}

</figure>
