{"contents":"{%- assign carousel_id = include.id | default: 'landing-social-carousel' -%}
{%- assign slides = site.data.social_carousel -%}

<div id="{{ carousel_id }}" class="carousel slide profile-carousel z-depth-1 rounded" data-ride="carousel" data-interval="6000">
  <ol class="carousel-indicators">
    {%- for slide in slides -%}
    <li data-target="#{{ carousel_id }}" data-slide-to="{{ forloop.index0 }}"{% if forloop.first %} class="active"{% endif %}></li>
    {%- endfor -%}
  </ol>

  <div class="carousel-inner rounded">
    {%- for slide in slides -%}
    <div class="carousel-item{% if forloop.first %} active{% endif %}">
      <img
        src="{{ slide.path | relative_url }}"
        class="d-block w-100 img-fluid rounded"
        alt="{{ slide.alt }}"
      />
      {%- if slide.caption -%}
      <div class="caption profile-carousel-caption">{{ slide.caption }}</div>
      {%- endif -%}
    </div>
    {%- endfor -%}
  </div>

  <a class="carousel-control-prev" href="#{{ carousel_id }}" role="button" data-slide="prev" aria-label="Previous slide">
    <span class="carousel-control-prev-icon" aria-hidden="true"></span>
  </a>
  <a class="carousel-control-next" href="#{{ carousel_id }}" role="button" data-slide="next" aria-label="Next slide">
    <span class="carousel-control-next-icon" aria-hidden="true"></span>
  </a>
</div>
